        return obj.fget
    raise InvalidTypeError(f"Expected function, got {type(obj).__name__}: {module}.{qualname}")


def get_name_in_module(module: str, qualname: str, attr_getter: Optional[
    Callable[[Any, str], Any]]=None) ->Any:
    try:
        mod = importlib.import_module(module)
    except ImportError:
        raise NameLookupError(f"Cannot import module: {module}")

    if attr_getter is None:
        attr_getter = getattr

    parts = qualname.split('.')
    obj = mod

    for part in parts:
        try:
            obj = attr_getter(obj, part)
        except AttributeError:
            raise NameLookupError(f"Cannot find {qualname} in module {module}")

    return obj
